  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','GENEROS','CAMPANHA_DE_AGUA','Uma campanha escolar afirma: “Feche a torneira enquanto ensaboa as mãos. Em uma semana, a escola reduziu o consumo em 12%.” O dado e o imperativo servem principalmente para','["mobilizar o público para manter uma prática, apoiando-a com um resultado.","registrar oficialmente uma decisão administrativa já encerrada.","contar uma história ficcional sobre desperdício.","apresentar instruções sem qualquer intenção de influenciar o leitor."]'::jsonb,'"mobilizar o público para manter uma prática, apoiando-a com um resultado."'::jsonb,'A orientação sugere uma ação e o resultado procura mostrar sua relevância, característica de comunicação de campanha.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-genre-02","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_IDENTIFY_GENRE_PURPOSE","purpose":"PROBE","difficulty":"EASY","cognitive_process":"INFER","context_family":"CAMPANHA_DE_AGUA","error_focus":"Ignorar que informação e persuasão podem coexistir.","remediation_hint":"Separe a instrução apresentada do efeito que a campanha espera produzir no público.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-genre-02') returning id into v_question_id;
