  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','GENEROS','ALERTA_DE_CHUVA','Uma mensagem oficial informa nível do rio, bairros em atenção e canais de emergência. Ela usa frases curtas e dados com horário. Qual efeito essas escolhas favorecem?','["A construção de suspense ficcional.","A defesa de uma opinião sem evidências.","A memorização de um conteúdo literário.","A consulta rápida de informações úteis para decisões imediatas."]'::jsonb,'"A consulta rápida de informações úteis para decisões imediatas."'::jsonb,'Em um alerta, concisão, horário e dados localizados ajudam o público a agir com rapidez.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-genre-11","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_IDENTIFY_GENRE_PURPOSE","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"ALERTA_DE_CHUVA","error_focus":"Desconsiderar a situação de urgência ao interpretar a forma.","remediation_hint":"Relacione o tempo disponível do leitor às escolhas de organização e linguagem.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-genre-11') returning id into v_question_id;
