  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','GENEROS','NOTA_DE_CORRECAO','Um portal publica uma nota corrigindo uma data errada em reportagem anterior e explica a alteração. Qual função é central nessa nota?','["Apagar a existência da reportagem anterior.","Anunciar um produto relacionado ao tema.","Retificar informação publicada e tornar a correção transparente.","Narrar uma experiência sem relação com o erro."]'::jsonb,'"Retificar informação publicada e tornar a correção transparente."'::jsonb,'A nota identifica e corrige um dado, permitindo ao leitor acompanhar a mudança editorial.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-genre-16","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_IDENTIFY_GENRE_PURPOSE","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"NOTA_DE_CORRECAO","error_focus":"Confundir correção pública com simples atualização sem explicação.","remediation_hint":"Verifique se a mensagem identifica o dado anterior e informa o que foi corrigido.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-genre-16') returning id into v_question_id;
