  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','AVALIACAO_DE_BIBLIOTECA','“A biblioteca recebeu 380 visitantes em maio, portanto é a melhor da cidade.” O que se pode concluir apenas pela frase?','["A comparação está provada porque a frase apresenta um número.","Toda a frase é opinião, pois a conclusão é avaliativa.","A quantidade e o mês são verificáveis; a conclusão comparativa exige critério e dados de outras bibliotecas.","O número é automaticamente falso porque há uma avaliação."]'::jsonb,'"A quantidade e o mês são verificáveis; a conclusão comparativa exige critério e dados de outras bibliotecas."'::jsonb,'O dado pode ser consultado; “melhor” exige definir critérios e comparar alternativas de forma adequada.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-02","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"EVALUATE","context_family":"AVALIACAO_DE_BIBLIOTECA","error_focus":"Usar uma estatística isolada para provar um superlativo.","remediation_hint":"Pergunte que população e quais critérios são necessários para sustentar a comparação.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-02') returning id into v_question_id;
