  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','PESQUISA_DE_LEITURA','Um texto afirma: “Em uma enquete voluntária do grêmio, 62 de 100 respondentes preferiram ampliar o horário da biblioteca.” Qual descrição é mais rigorosa?','["A maioria de todos os estudantes foi comprovada sem margem de dúvida.","O resultado descreve os respondentes da enquete; não representa automaticamente todos os estudantes.","A frase é somente opinião porque trata de preferência.","O número não pode ser verificado por haver escolha voluntária."]'::jsonb,'"O resultado descreve os respondentes da enquete; não representa automaticamente todos os estudantes."'::jsonb,'A quantidade é verificável na enquete, mas a amostra voluntária limita a generalização.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-03","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"PESQUISA_DE_LEITURA","error_focus":"Generalizar uma amostra de adesão voluntária para toda a população.","remediation_hint":"Confira quem respondeu, como foi selecionado e a qual grupo a conclusão se refere.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-03') returning id into v_question_id;
