  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','RESENHA_DE_LIVRO','“O romance foi publicado em 2018 e é uma leitura emocionante.” Como as duas partes se classificam?','["Ano de publicação verificável; “emocionante” é avaliação de experiência.","As duas são fatos porque aparecem em uma resenha.","As duas são opiniões porque falam de literatura.","Ano de publicação é opinião; “emocionante” é uma medida objetiva."]'::jsonb,'"Ano de publicação verificável; “emocionante” é avaliação de experiência."'::jsonb,'A data pode ser consultada em registros editoriais; a reação emocional expressa avaliação do leitor.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-04","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"PRACTICE","difficulty":"EASY","cognitive_process":"DISTINGUISH","context_family":"RESENHA_DE_LIVRO","error_focus":"Classificar pelo assunto em vez do tipo de afirmação.","remediation_hint":"Pergunte se diferentes leitores poderiam discordar sem erro factual e que registro confirmaria a data.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-04') returning id into v_question_id;
