  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','NOTICIA_DE_CLIMA','“A estação registrou 31 mm de chuva; foi uma quantidade preocupante.” O que falta para avaliar a segunda parte?','["Uma forma de transformar milímetros em opinião.","Prova de que nenhuma chuva ocorreu.","A remoção do dado medido, pois ele impede qualquer análise.","Um critério ou contexto de comparação que explique por que o volume preocupa."]'::jsonb,'"Um critério ou contexto de comparação que explique por que o volume preocupa."'::jsonb,'O volume é uma medição; a qualificação depende de risco local, período, histórico ou limiar adotado.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-05","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"EVALUATE","context_family":"NOTICIA_DE_CLIMA","error_focus":"Aceitar uma avaliação como autoevidente sem critério.","remediation_hint":"Procure o padrão de comparação e a consequência que justificaria a avaliação.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-05') returning id into v_question_id;
