  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','PROPAGANDA_DE_ALIMENTO','“Este é o lanche mais saudável da escola.” Que elemento é necessário para avaliar essa afirmação?','["Critérios nutricionais definidos e comparação consistente com outros lanches.","Apenas o tamanho do título no anúncio.","A opinião do anunciante como prova suficiente.","A comprovação de que o lanche tem embalagem colorida."]'::jsonb,'"Critérios nutricionais definidos e comparação consistente com outros lanches."'::jsonb,'“Mais saudável” é uma comparação avaliativa que exige dimensões e dados comparáveis.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-08","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"IDENTIFY","context_family":"PROPAGANDA_DE_ALIMENTO","error_focus":"Aceitar superlativos sem definição nem comparação.","remediation_hint":"Defina o que significa saudável para a avaliação e quais dados podem sustentar a comparação.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-08') returning id into v_question_id;
