  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','AVALIACAO_DE_APLICATIVO','“O aplicativo respondeu em 2 segundos no teste de hoje e tem a interface mais intuitiva.” Qual evidência sustenta diretamente apenas uma das partes?','["O registro de tempo pode sustentar os 2 segundos; “mais intuitiva” exige critério e comparação com usuários.","A avaliação da interface comprova automaticamente o tempo.","Nenhuma parte pode ser testada porque é uma opinião sobre tecnologia.","As duas partes são fatos por aparecerem na mesma frase."]'::jsonb,'"O registro de tempo pode sustentar os 2 segundos; “mais intuitiva” exige critério e comparação com usuários."'::jsonb,'Tempo é mensurável sob protocolo; facilidade de uso demanda definição, tarefas e dados de usuários.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-11","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"AVALIACAO_DE_APLICATIVO","error_focus":"Usar uma medição simples para validar uma avaliação diferente.","remediation_hint":"Associe a cada afirmação seu próprio método de verificação.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-11') returning id into v_question_id;
