  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','PESQUISA_DE_SATISFACAO','Uma pesquisa com 40 clientes de uma loja atribui nota média 8,4 ao atendimento. A gerente conclui: “nosso atendimento é excelente para toda a cidade”. Qual ressalva é mais pertinente?','["A média torna a pesquisa inútil em qualquer situação.","A nota 8,4 demonstra que todos deram a mesma avaliação.","A amostra e o critério de “excelente” limitam a generalização para toda a cidade.","Uma opinião não pode ser resumida por uma escala numérica."]'::jsonb,'"A amostra e o critério de “excelente” limitam a generalização para toda a cidade."'::jsonb,'É preciso saber como os participantes foram selecionados e como a escala define excelência.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-12","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"PESQUISA_DE_SATISFACAO","error_focus":"Generalizar uma amostra local e não probabilística para uma população maior.","remediation_hint":"Examine quem respondeu, quem ficou de fora e qual nota foi definida como excelência.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-12') returning id into v_question_id;
