  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PORTUGUESE','LEITURA','DEBATE_DE_PATRIMONIO','“O prédio foi inaugurado em 1932; sua demolição seria uma perda irreparável.” Como tratar a segunda oração em um debate público?','["Como uma avaliação que pode ser argumentada com critérios históricos, culturais e sociais.","Como um dado cronológico confirmado pela primeira oração.","Como uma informação impossível de discutir por ser opinião.","Como prova de que o prédio nunca poderá ser alterado."]'::jsonb,'"Como uma avaliação que pode ser argumentada com critérios históricos, culturais e sociais."'::jsonb,'A data é verificável; a ideia de perda irreparável expressa valor, mas pode ser justificada por evidências e critérios.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-pt-fact-13","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PORTUGUESE_DISTINGUISH_FACT_OPINION","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"DEBATE_DE_PATRIMONIO","error_focus":"Confundir avaliação com arbitrariedade ou com fato comprovado.","remediation_hint":"Identifique valores envolvidos e evidências que poderiam sustentar ou contestar a avaliação.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-pt-fact-13') returning id into v_question_id;
