  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','EMAIL_A_PROFESSOR','A student emails a teacher: “Could you clarify the deadline when you have a moment?” What does “could you” mainly do in this request?','["It proves the student is uncertain about every fact.","It softens the request and signals a considerate tone.","It changes the deadline into a past event.","It makes the message an informal joke."]'::jsonb,'"It softens the request and signals a considerate tone."'::jsonb,'The modal phrasing makes the request less direct; the relationship and email context support that reading.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-01","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PROBE","difficulty":"EASY","cognitive_process":"COMPARE","context_family":"EMAIL_A_PROFESSOR","error_focus":"Ler a forma modal apenas como habilidade física ou possibilidade literal.","remediation_hint":"Compare a formulação com um imperativo direto e considere a relação entre estudantes e docente.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-01') returning id into v_question_id;
