  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','IDIOM_IN_TEAM_CHAT','After a tense meeting, a colleague writes: “Let’s break the ice with a quick game.” What is the likely meaning?','["Help people feel more comfortable at the start of an interaction.","Damage a frozen object during the game.","Cancel the meeting permanently.","Ask everyone to leave the room."]'::jsonb,'"Help people feel more comfortable at the start of an interaction."'::jsonb,'The meeting context and the game suggest the idiom means easing social tension.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-02","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"EVALUATE","context_family":"IDIOM_IN_TEAM_CHAT","error_focus":"Traduzir uma expressão idiomática literalmente apesar do contexto social.","remediation_hint":"Pergunte que efeito um jogo inicial poderia ter sobre a tensão do grupo.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-02') returning id into v_question_id;
