  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','TEXT_TO_FRIEND','A friend texts “Sounds good, see you at six!” after an invitation. Which feature best fits the informal channel?','["A legal disclaimer and numbered clauses.","A complete report with cited sources.","A formal letter ending with a full postal address.","A short conversational reply with an omitted formal greeting."]'::jsonb,'"A short conversational reply with an omitted formal greeting."'::jsonb,'A concise conversational response is common in a familiar relationship and messaging channel.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-03","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"TEXT_TO_FRIEND","error_focus":"Treating informal language as incorrect rather than situational.","remediation_hint":"Relate message length and greeting style to the familiar interlocutors and channel.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-03') returning id into v_question_id;
