  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','CUSTOMER_SERVICE_EMAIL','A customer writes “I would appreciate your help with the missing order.” Why might this phrasing be chosen in a service email?','["It hides that an order is missing.","It makes the writer''s message a joke.","It states a request politely while identifying the issue.","It proves the order was delivered."]'::jsonb,'"It states a request politely while identifying the issue."'::jsonb,'The conditional and appreciative wording frames a clear request in a service interaction.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-04","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PRACTICE","difficulty":"EASY","cognitive_process":"INTERPRET","context_family":"CUSTOMER_SERVICE_EMAIL","error_focus":"Confusing courteous wording with lack of a concrete request.","remediation_hint":"Identify the problem and the action requested beneath the polite framing.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-04') returning id into v_question_id;
