  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','SCHOOL_SIGN','A sign in a shared laboratory says “Please leave the bench clean for the next group.” What does “please” contribute?','["It changes the sign into a personal story.","It frames the instruction courteously without removing its practical request.","It means the instruction is optional in every circumstance.","It identifies the next group by name."]'::jsonb,'"It frames the instruction courteously without removing its practical request."'::jsonb,'“Please” mitigates the directive; the request still asks users to clean the bench.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-05","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"SCHOOL_SIGN","error_focus":"Assuming polite wording makes an instruction disappear.","remediation_hint":"Separate the courteous marker from the action the sign asks readers to take.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-05') returning id into v_question_id;
