  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','MEETING_INVITATION','A host writes “You are welcome to join us, but there is no pressure.” What does the second clause do in this invitation?','["It guarantees that the event has no cost.","It means the host does not want anyone to attend.","It changes the invitation into a required meeting.","It reduces the obligation and signals that declining is acceptable."]'::jsonb,'"It reduces the obligation and signals that declining is acceptable."'::jsonb,'The phrase explicitly lowers social pressure while leaving the invitation open.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-07","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"MEETING_INVITATION","error_focus":"Inferir uma recusa do anfitrião quando o texto mantém o convite.","remediation_hint":"Leia as duas partes juntas: convite e ressalva sobre obrigação.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-07') returning id into v_question_id;
