  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','CULTURAL_REFERENCE_HOLIDAY','A school newsletter names a local holiday and links to a community page explaining its history. Why is the link useful for readers unfamiliar with it?','["It proves every family celebrates the holiday in the same way.","It replaces the newsletter''s purpose with advertising.","It supplies context rather than assuming every reader shares the same background knowledge.","It shows that local references should never appear in school communication."]'::jsonb,'"It supplies context rather than assuming every reader shares the same background knowledge."'::jsonb,'The link makes a reference more accessible to readers with different experiences.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-08","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"CULTURAL_REFERENCE_HOLIDAY","error_focus":"Assuming shared cultural knowledge across a diverse audience.","remediation_hint":"Consider which readers may need explanation and what information the link provides.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-08') returning id into v_question_id;
