  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ENGLISH','CULTURA','ONLINE_COMMENT','A post says “That plan is bold.” Replies disagree about whether “bold” is praise or criticism. What additional context would help?','["The surrounding argument, tone markers and the writer''s response to the plan.","The number of letters in the word.","The writer''s nationality alone, treated as decisive.","A dictionary entry that excludes all contextual uses."]'::jsonb,'"The surrounding argument, tone markers and the writer''s response to the plan."'::jsonb,'“Bold” can be approving or critical; local discourse and interaction provide evidence for the intended evaluation.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-eng-culture-10","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ENGLISH_RELATE_LANGUAGE_CULTURE","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"ANALYZE","context_family":"ONLINE_COMMENT","error_focus":"Treating a word with multiple pragmatic readings as unambiguous.","remediation_hint":"Find nearby reactions and reasons before deciding the writer''s stance.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-eng-culture-10') returning id into v_question_id;
