  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHYSICS','MOVIMENTO','VELOCIDADE_VS_POSICAO','Um estudante afirma: “No gráfico posição-tempo, quanto mais alto o ponto, maior a velocidade.” Qual correção é adequada?','["A altura sempre indica aceleração.","A altura indica posição; a velocidade é dada pela inclinação do gráfico.","A velocidade não pode ser representada em gráficos.","A afirmação é correta em qualquer escala."]'::jsonb,'"A altura indica posição; a velocidade é dada pela inclinação do gráfico."'::jsonb,'O valor vertical é a posição; a taxa de variação da posição no tempo é a velocidade.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phys-graph-15","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHYSICS_INTERPRET_MOTION_GRAPH","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitive_process":"EXPLAIN","context_family":"VELOCIDADE_VS_POSICAO","error_focus":"Confundir valor instantâneo da grandeza com sua taxa de variação.","remediation_hint":"Distinga coordenada vertical e inclinação entre dois pontos.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phys-graph-15') returning id into v_question_id;
