  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','CHEMISTRY','REACOES','GELO_DERRETENDO','Um cubo de gelo derrete e vira água líquida, sem outro material presente. O que se pode concluir?','["Uma reação criou uma substância nova.","Ocorreu mudança física de estado; a substância continua sendo água.","O oxigênio deixou de existir.","A massa necessariamente desapareceu."]'::jsonb,'"Ocorreu mudança física de estado; a substância continua sendo água."'::jsonb,'Derreter muda estado físico, mas não altera a identidade química da água.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-chem-reaction-01","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"CHEMISTRY_REACTION_EVIDENCE","purpose":"PROBE","difficulty":"EASY","cognitive_process":"DISTINGUISH","context_family":"GELO_DERRETENDO","error_focus":"Classificar toda mudança visível como reação química.","remediation_hint":"Pergunte se houve formação de substância diferente ou apenas mudança de estado.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-chem-reaction-01') returning id into v_question_id;
