  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','CHEMISTRY','REACOES','TABLETE_EFERVESCENTE','Um tablete efervescente em água libera gás; a mistura fica mais fria. O que essas observações sustentam melhor?','["Há evidências de reação e troca de energia, mas a identificação dos produtos exige dados adicionais.","O gás é necessariamente vapor de água por ebulição.","A mistura fria prova que nenhuma reação ocorreu.","A mudança de temperatura determina sozinha a equação completa."]'::jsonb,'"Há evidências de reação e troca de energia, mas a identificação dos produtos exige dados adicionais."'::jsonb,'Liberação de gás e mudança térmica são pistas convergentes, mas não identificam sozinhas toda a composição.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-chem-reaction-06","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"CHEMISTRY_REACTION_EVIDENCE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"TABLETE_EFERVESCENTE","error_focus":"Extrapolar observações para uma equação ou produto não medido.","remediation_hint":"Separe evidência de transformação da identificação específica dos produtos.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-chem-reaction-06') returning id into v_question_id;
