  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','CHEMISTRY','REACOES','QUEIMA_DE_VELA','Uma vela acesa diminui de tamanho, libera gases e calor. Por que uma balança aberta pode indicar perda de massa no conjunto visível?','["A matéria foi destruída pela chama.","O oxigênio não participa da combustão.","Produtos gasosos se dispersam para o ambiente fora do limite medido.","A conservação da massa não se aplica a reações."]'::jsonb,'"Produtos gasosos se dispersam para o ambiente fora do limite medido."'::jsonb,'Em sistema aberto, parte dos produtos gasosos deixa a região pesada; se o sistema incluir gases, a matéria total se conserva.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-chem-reaction-08","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"CHEMISTRY_REACTION_EVIDENCE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"QUEIMA_DE_VELA","error_focus":"Confundir sistema medido com o sistema completo da reação.","remediation_hint":"Defina o limite do sistema e identifique para onde os gases se deslocaram.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-chem-reaction-08') returning id into v_question_id;
