  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','CHEMISTRY','REACOES','PRODUTO_DE_LIMPEZA','Misturar dois produtos de limpeza pode liberar gás perigoso. Que decisão científica e segura é apropriada?','["Não misturar; consultar rótulos e orientações de segurança, pois a interação pode gerar produtos tóxicos.","Testar em pequena quantidade sem proteção para identificar o gás.","Misturar em recipiente fechado para conservar a massa.","Concluir que produtos domésticos nunca reagem."]'::jsonb,'"Não misturar; consultar rótulos e orientações de segurança, pois a interação pode gerar produtos tóxicos."'::jsonb,'A possibilidade de produtos perigosos exige prevenção; não se deve propor experimento inseguro para confirmar uma hipótese.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-chem-reaction-14","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"CHEMISTRY_REACTION_EVIDENCE","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"ANALYZE","context_family":"PRODUTO_DE_LIMPEZA","error_focus":"Priorizar observação experimental sobre risco previsível.","remediation_hint":"Avalie segurança e informação do fabricante antes de qualquer teste.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-chem-reaction-14') returning id into v_question_id;
