  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','CHEMISTRY','REACOES','ESTADO_VS_SUBSTANCIA','Por que congelar água não é, por si só, evidência de reação química?','["Porque sólidos nunca participam de reações.","Porque o estado mudou, mas a substância continua sendo H₂O.","Porque a massa desaparece ao congelar.","Porque moléculas deixam de existir no gelo."]'::jsonb,'"Porque o estado mudou, mas a substância continua sendo H₂O."'::jsonb,'A mudança de fase altera organização e movimento das partículas, não a identidade da substância.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-chem-reaction-15","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"CHEMISTRY_REACTION_EVIDENCE","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitive_process":"EXPLAIN","context_family":"ESTADO_VS_SUBSTANCIA","error_focus":"Confundir alteração macroscópica com mudança de composição.","remediation_hint":"Compare a fórmula química antes e depois da mudança de estado.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-chem-reaction-15') returning id into v_question_id;
