  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','BIOLOGY','ECOLOGIA','ABUNDANCIA_E_DENSIDADE','Qual afirmação diferencia abundância de densidade?','["Densidade é sempre maior que abundância.","Abundância é uma taxa por área.","Os termos indicam exatamente a mesma medida.","Abundância conta indivíduos; densidade relaciona indivíduos à área ou volume."]'::jsonb,'"Abundância conta indivíduos; densidade relaciona indivíduos à área ou volume."'::jsonb,'Densidade exige um denominador espacial, enquanto abundância é a contagem total definida.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-bio-pop-04","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"BIOLOGY_INTERPRET_POPULATION_DATA","purpose":"PRACTICE","difficulty":"EASY","cognitive_process":"DISTINGUISH","context_family":"ABUNDANCIA_E_DENSIDADE","error_focus":"Usar os termos como sinônimos.","remediation_hint":"Confira se a medida inclui área ou volume no denominador.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-bio-pop-04') returning id into v_question_id;
