  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','BIOLOGY','ECOLOGIA','CONTAGEM_DE_POLINIZADORES','Dois jardins iguais foram observados por 2 h e 4 h, respectivamente. Registraram-se 24 polinizadores no primeiro e 36 no segundo. Qual comparação por esforço é correta?','["O segundo tem necessariamente 50% mais população.","Ambos têm 60 polinizadores por hora.","Não há como usar o tempo na análise.","12 e 9 polinizadores por hora, respectivamente."]'::jsonb,'"12 e 9 polinizadores por hora, respectivamente."'::jsonb,'Divida cada contagem pelo próprio tempo: 24/2=12 e 36/4=9 polinizadores por hora. O segundo número bruto é maior, mas a taxa de detecção por esforço é menor.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-bio-pop-13","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"BIOLOGY_INTERPRET_POPULATION_DATA","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"CONTAGEM_DE_POLINIZADORES","error_focus":"Comparar contagens brutas sem padronizar o tempo de observação.","remediation_hint":"Calcule contagem dividida pelo tempo em cada local antes de comparar.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-bio-pop-13') returning id into v_question_id;
