  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','GEOGRAPHY','CARTOGRAFIA','ESCALAS_DIFERENTES','Qual mapa tem escala maior: 1:25.000 ou 1:250.000?','["1:250.000, pois o denominador maior sempre significa escala maior.","São iguais porque ambos começam por 1.","1:25.000, pois representa área menor com mais detalhe.","Não é possível comparar escalas numéricas."]'::jsonb,'"1:25.000, pois representa área menor com mais detalhe."'::jsonb,'Denominador menor significa menor redução e escala cartográfica maior.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-geo-scale-05","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"GEOGRAPHY_MAP_SCALE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"ESCALAS_DIFERENTES","error_focus":"Interpretar escala maior como denominador numericamente maior.","remediation_hint":"Compare quanta realidade cada centímetro representa e a área coberta.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-geo-scale-05') returning id into v_question_id;
