  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','GEOGRAPHY','CARTOGRAFIA','AMPLIACAO_DE_MAPA','Um mapa impresso em escala 1:50.000 é ampliado para o dobro do tamanho, mas a legenda numérica não é atualizada. Como interpretar medidas feitas com a legenda antiga?','["A escala efetiva muda; é preciso recalibrar com a barra gráfica ou corrigir a legenda.","A escala permanece idêntica porque a impressão é a mesma.","A distância real dobra junto com o papel.","A ampliação não afeta medidas cartográficas."]'::jsonb,'"A escala efetiva muda; é preciso recalibrar com a barra gráfica ou corrigir a legenda."'::jsonb,'Ao ampliar só o mapa sem atualizar a escala numérica, cada centímetro passa a cobrir outra distância real.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-geo-scale-10","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"GEOGRAPHY_MAP_SCALE","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"AMPLIACAO_DE_MAPA","error_focus":"Usar uma razão antiga após redimensionamento não proporcional ao indicador.","remediation_hint":"Compare o mapa com a escala gráfica e determine o fator de ampliação.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-geo-scale-10') returning id into v_question_id;
