  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','GEOGRAPHY','CLIMA','MEDIA_E_EXTREMOS','Duas cidades têm média anual de 22°C. Uma varia de 18 a 26°C e outra de 5 a 35°C. O que a média não revela?','["As cidades têm necessariamente o mesmo clima em todos os meses.","A amplitude e a variabilidade térmica são muito diferentes.","A média não pode ser calculada.","A segunda cidade tem menor amplitude."]'::jsonb,'"A amplitude e a variabilidade térmica são muito diferentes."'::jsonb,'Médias iguais podem coexistir com amplitudes e padrões sazonais distintos.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-geo-climate-09","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"GEOGRAPHY_ANALYZE_CLIMATE_DATA","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"MEDIA_E_EXTREMOS","error_focus":"Tratar médias iguais como séries idênticas.","remediation_hint":"Compare máximos, mínimos e distribuição ao longo do ano.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-geo-climate-09') returning id into v_question_id;
