  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHILOSOPHY','ETICA','PRIVACIDADE_E_PROTECAO','Uma estudante relata que um colega ameaça divulgar fotos privadas de outra pessoa. Qual primeira resposta combina proteção e proporcionalidade?','["Verificar o risco e acionar apoio responsável, compartilhando apenas o necessário.","Repostar a ameaça para que todos saibam quem fez.","Ignorar, porque a conversa era informal.","Punir toda a turma antes de entender o caso."]'::jsonb,'"Verificar o risco e acionar apoio responsável, compartilhando apenas o necessário."'::jsonb,'A resposta procura proteger a pessoa e verificar os fatos sem ampliar a exposição nem presumir culpa coletiva.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phil-ethics-01","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHILOSOPHY_APPLY_ETHICAL_PRINCIPLE","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"PRIVACIDADE_E_PROTECAO","error_focus":"Escolher apenas a consequência mais conveniente e ignorar direitos.","remediation_hint":"Em cada caso, registre: fatos, envolvidos, princípio em conflito, alternativa menos danosa e razão que sustenta sua decisão.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phil-ethics-01') returning id into v_question_id;
