  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHILOSOPHY','ETICA','UNIVERSALIZACAO','Uma pessoa defende colar em provas sempre que acredita que não será descoberta. Qual pergunta testa a consistência dessa máxima?','["Quantas pessoas já colaram sem serem vistas?","A pessoa costuma tirar notas altas?","A prova era difícil?","O que ocorreria se todos adotassem a mesma regra e a avaliação dependesse de confiança?"]'::jsonb,'"O que ocorreria se todos adotassem a mesma regra e a avaliação dependesse de confiança?"'::jsonb,'Universalizar a máxima revela que a prática enfraqueceria a confiança e o propósito da avaliação que ela usa.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phil-ethics-04","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHILOSOPHY_APPLY_ETHICAL_PRINCIPLE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"UNIVERSALIZACAO","error_focus":"Escolher apenas a consequência mais conveniente e ignorar direitos.","remediation_hint":"Em cada caso, registre: fatos, envolvidos, princípio em conflito, alternativa menos danosa e razão que sustenta sua decisão.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phil-ethics-04') returning id into v_question_id;
