  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHILOSOPHY','ETICA','JUSTICA_E_EQUIDADE','Dois estudantes recebem materiais em formatos diferentes para que ambos consigam ler. Qual princípio melhor explica a decisão?','["Equidade: ajustar o apoio para assegurar oportunidade de participação.","Privilégio sem justificativa, pois recursos devem ser sempre idênticos.","Punição por diferença de desempenho.","Neutralidade que ignora barreiras."]'::jsonb,'"Equidade: ajustar o apoio para assegurar oportunidade de participação."'::jsonb,'Equidade considera barreiras relevantes e oferece condições adequadas, sem exigir que o recurso seja idêntico.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phil-ethics-05","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHILOSOPHY_APPLY_ETHICAL_PRINCIPLE","purpose":"PRACTICE","difficulty":"EASY","cognitive_process":"DISTINGUISH","context_family":"JUSTICA_E_EQUIDADE","error_focus":"Escolher apenas a consequência mais conveniente e ignorar direitos.","remediation_hint":"Em cada caso, registre: fatos, envolvidos, princípio em conflito, alternativa menos danosa e razão que sustenta sua decisão.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phil-ethics-05') returning id into v_question_id;
