  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHILOSOPHY','ETICA','AUTONOMIA_E_CONSENTIMENTO','Uma equipe quer usar a voz gravada de uma colega em um vídeo escolar. Qual procedimento respeita melhor sua autonomia?','["Usar a gravação porque foi feita dentro da escola.","Pedir autorização somente depois que o vídeo viralizar.","Explicar finalidade e circulação e pedir autorização antes de publicar.","Ocultar o nome, ainda que a voz seja reconhecível."]'::jsonb,'"Explicar finalidade e circulação e pedir autorização antes de publicar."'::jsonb,'Consentimento informado requer conhecer propósito e alcance antes do uso; anonimização parcial não substitui autorização.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phil-ethics-06","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHILOSOPHY_APPLY_ETHICAL_PRINCIPLE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"AUTONOMIA_E_CONSENTIMENTO","error_focus":"Escolher apenas a consequência mais conveniente e ignorar direitos.","remediation_hint":"Em cada caso, registre: fatos, envolvidos, princípio em conflito, alternativa menos danosa e razão que sustenta sua decisão.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phil-ethics-06') returning id into v_question_id;
