  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHILOSOPHY','ETICA','DESCRICAO_E_NORMA','''Muitos colegas compartilham a senha'' é uma descrição. Qual frase acrescenta uma avaliação normativa?','["A senha tem oito caracteres.","O grupo tem vinte estudantes.","Compartilhar a senha sem autorização é inadequado porque expõe dados de outras pessoas.","A plataforma registrou acessos ontem."]'::jsonb,'"Compartilhar a senha sem autorização é inadequado porque expõe dados de outras pessoas."'::jsonb,'A segunda afirma o que deveria ou não ser feito e oferece uma razão; as demais descrevem fatos verificáveis.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phil-ethics-18","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHILOSOPHY_APPLY_ETHICAL_PRINCIPLE","purpose":"REVIEW","difficulty":"EASY","cognitive_process":"DISTINGUISH","context_family":"DESCRICAO_E_NORMA","error_focus":"Escolher apenas a consequência mais conveniente e ignorar direitos.","remediation_hint":"Em cada caso, registre: fatos, envolvidos, princípio em conflito, alternativa menos danosa e razão que sustenta sua decisão.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phil-ethics-18') returning id into v_question_id;
