  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHILOSOPHY','ETICA','RAZOES_E_CONTRAEXEMPLO','Uma regra afirma: ''Toda decisão por votação é justa''. Qual contraexemplo é mais relevante?','["Uma votação ocorreu numa terça-feira.","Uma votação exclui do voto justamente as pessoas que sofrerão o maior impacto.","A urna era de papel.","O resultado foi anunciado cedo."]'::jsonb,'"Uma votação exclui do voto justamente as pessoas que sofrerão o maior impacto."'::jsonb,'O caso mostra que o procedimento de votação, sozinho, não garante inclusão nem justiça do processo.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phil-ethics-19","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHILOSOPHY_APPLY_ETHICAL_PRINCIPLE","purpose":"REVIEW","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"RAZOES_E_CONTRAEXEMPLO","error_focus":"Escolher apenas a consequência mais conveniente e ignorar direitos.","remediation_hint":"Em cada caso, registre: fatos, envolvidos, princípio em conflito, alternativa menos danosa e razão que sustenta sua decisão.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phil-ethics-19') returning id into v_question_id;
