  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','PHILOSOPHY','CONCEITO','VALIDADE_LOGICA','Considere: ''Todos os mamíferos observados respiram; baleias são mamíferos; logo, baleias respiram''. Se as premissas forem verdadeiras, a conclusão segue?','["Sim, a forma liga a classe geral ao caso particular.","Não, porque baleias vivem na água.","Não, pois toda conclusão é opinião.","Só se houver uma votação."]'::jsonb,'"Sim, a forma liga a classe geral ao caso particular."'::jsonb,'A estrutura é dedutivamente válida: se todos os membros da classe têm a propriedade e baleias pertencem à classe, então a conclusão segue.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-phil-argument-02","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"PHILOSOPHY_DISTINGUISH_CONCEPT","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"EVALUATE","context_family":"VALIDADE_LOGICA","error_focus":"Confundir conclusão convincente com conclusão demonstrada.","remediation_hint":"Sublinhe a conclusão, numere as premissas e escreva uma pergunta de verificação para cada evidência ou pressuposto.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-phil-argument-02') returning id into v_question_id;
