  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ART','INTERPRETACAO','CONTRASTE_CROMATICO','Uma composição usa um único quadrado amarelo sobre um campo azul escuro. Qual efeito formal pode ser descrito com evidência?','["A obra prova que o artista gosta de verão.","Não há relação entre as cores.","O quadrado é necessariamente um símbolo religioso.","O contraste de cor tende a destacar o quadrado."]'::jsonb,'"O contraste de cor tende a destacar o quadrado."'::jsonb,'A diferença cromática é observável e pode produzir destaque; significados pessoais exigiriam outras evidências.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-art-interpret-01","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ART_INTERPRET_WORK","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"CONTRASTE_CROMATICO","error_focus":"Pular a descrição e afirmar um significado sem apontar evidências.","remediation_hint":"Use a sequência: observo..., noto a relação..., isso pode sugerir..., porque...; diferencie hipótese de informação documentada.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-art-interpret-01') returning id into v_question_id;
