  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.3 journey expansion','ART','INTERPRETACAO','LINHAS_E_DIRECAO','Linhas diagonais convergem para uma figura pequena no canto. Qual leitura está mais bem sustentada?','["A figura é certamente uma pessoa real conhecida pelo artista.","A obra não tem composição.","A convergência pode conduzir o olhar à figura, embora ela ocupe pouca área.","Linhas diagonais sempre significam perigo."]'::jsonb,'"A convergência pode conduzir o olhar à figura, embora ela ocupe pouca área."'::jsonb,'A direção das linhas sustenta a leitura sobre percurso visual, sem impor um significado universal.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v93-art-interpret-02","content_version":"tec-escola-core-v9.3-journey-expansion-v1","primary_skill":"ART_INTERPRET_WORK","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"LINHAS_E_DIRECAO","error_focus":"Pular a descrição e afirmar um significado sem apontar evidências.","remediation_hint":"Use a sequência: observo..., noto a relação..., isso pode sugerir..., porque...; diferencie hipótese de informação documentada.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v93-art-interpret-02') returning id into v_question_id;
